{"code":"import json, time
with open('table.json') as f: table=json.load(f)
with open('start.txt') as f: s=f.read().strip()
print('start', s, len(s))

def step(state):
    n=len(state)
    return ''.join(table[state[(i-1)%n]+state[i]+state[(i+1)%n]] for i in range(n))
seen={s:0}
state=s
T=2000000
st=time.time()
for t in range(1,T+1):
    state=step(state)
    if state in seen:
        print('cycle found at t',t,'first',seen[state],'period',t-seen[state])
        break
    seen[state]=t
    if t%200000==0:
        print('t',t,'elapsed',time.time()-st)
else:
    print('no cycle up to',T,'unique',len(seen),'elapsed',time.time()-st,'last',state)
